import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import Table from 'react-bootstrap/Table';
import {
    CButton,
    CCol,
    CInput,
    CRow
  } from '@coreui/react';
import CIcon from '@coreui/icons-react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import Select from 'react-select';
import { yesAndNoList, unitOfMeasurementsList } from 'src/Utils/Enums';
import { BACKEND_PRICE_TRACKER_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';


//default
const FILE_NAME = "ExpensesView.js";

const temporalFilterOptions = [
    { value: 'DATE', label: 'Date' },
    { value: 'MONTH', label: 'Month' },
    { value: 'YEAR', label: 'Year' }
];

//default
const initialState = {
    isLoaded: false,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    categoryListData: [],
    productListData: [],
    expensesListData: [],
    filterItems : {
        temporalFilter: temporalFilterOptions[1],
        temporalValueFilter: moment().format('YYYY-MM-DD'),
        productFilter: null,
        categoryFilter: null
    },
    filtersEngaged: true,
    filteredExpensesListData: []
};


class ExpensesView extends Component {

    //default
    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    //default
    componentDidMount() {
        document.title = "Expenses - view";
        this.fetchCategoryDataList();
        this.fetchProductDataList();
        this.fetchExpenseDataList();
    }

    //default
    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    //default
    reloadData() {
        this.resetStateToDefault();
        this.fetchCategoryDataList();
        this.fetchProductDataList();
        this.fetchExpenseDataList();
    }

    fetchCategoryDataList() {
        let API_URL = BACKEND_PRICE_TRACKER_SERVICE_BASE_URL + '/category/list?offset=0&from=admin-portal';
        const userData = getUserDataFromLocalStorage();

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if(response.status === 200)
                return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchCategoryDataList", "FETCH_1", "result", result);
                if(result.code === 1001) {
                    this.setState({
                        categoryListData: result.data
                    });
                }
            },
            (error) => {
                Logger(FILE_NAME, "fetchCategoryDataList", "FETCH_1", "error", error);
            }
        );
    }

    fetchProductDataList() {
        let API_URL = BACKEND_PRICE_TRACKER_SERVICE_BASE_URL + '/product/list?offset=0&from=admin-portal';
        const userData = getUserDataFromLocalStorage();

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if(response.status === 200)
                return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchProductDataList", "FETCH_1", "result", result);
                if(result.code === 1001) {
                    const productListDataSelectTagSpecific = result.data.map((product) => {
                        return {
                            value: product.id,
                            label: product.name
                        };
                    });
                    this.setState({
                        productListData: result.data,
                        productListDataSelectTagSpecific
                    });
                }
            },
            (error) => {
                Logger(FILE_NAME, "fetchProductDataList", "FETCH_1", "error", error);
            }
        );
    }

    fetchExpenseDataList() {
        let API_URL = BACKEND_PRICE_TRACKER_SERVICE_BASE_URL + '/expense/list';
        const userData = getUserDataFromLocalStorage();

        const requestBody = {};
        const { temporalFilter, temporalValueFilter, categoryFilter, productFilter } = this.state.filterItems;
        if (temporalFilter !== null && temporalValueFilter !== null) {
            requestBody.temporal = {
                by: temporalFilter.value,
                value: temporalValueFilter
            };
        }
        if (categoryFilter !== null) {
            requestBody.categoryId = categoryFilter.value;
        }
        if (productFilter !== null) {
            requestBody.productId = productFilter.value;
        }

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(requestBody), userData.authToken))
        .then(response => {
            if(response.status === 200)
                return response.json();
            if(response.status === 401) {
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchExpenseDataList", "FETCH_1", "result", result);
                if(result.code === 1001) {
                    //success
                    this.setState({
                        isLoaded: true,
                        expensesListData: result.data,
                        filteredExpensesListData: result.data
                    });
                } else {
                    //something horrible happened
                    this.setState({
                        loadingModalVisible: false,
                        loadingModalState: 0,
                        failureModalVisible: true
                    });
                }
            },
            (error) => {
                Logger(FILE_NAME, "fetchExpenseDataList", "FETCH_1", "error", error);
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
        );
    }

    printStoreData(entry) {
        const store = entry.store;
        if (!store) return 'N/A';
        const storeLocation = entry.storeLocation;
        const locationStr = storeLocation
            ? (storeLocation.name + '(' + storeLocation.id + '), ' + storeLocation.description + ', ' + storeLocation.city)
            : 'N/A';
        return store.name + ' (🆔 :' + store.id + ') 📍 LOCATION : ' + locationStr;
    }

    printLocationData(entry) {
        const location = entry.location;
        if (!location) return '📍 LOCATION : N/A';
        return '📍 LOCATION : ' + location.name + '(' + location.id + '), ' + location.description + ', ' + location.city;
    }

    toggleFilter() {
        //this function will toggle the filter(s)
        this.setState({
            filtersEngaged: true,
            isLoaded: false
        });

        // temporal filter is server-side, re-fetch data from backend
        this.fetchExpenseDataList();
    }



    //default
    render() {
        //default
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ? 
            <div>
                <h1><u>EXPENSES VIEW</u>

                <br />
                    <div style={{
                            borderStyle:"solid",
                            borderColor:"#ff9100",
                            padding: "10px 10px 10px 10px",
                            margin: "0px 0px 10px 0px"
                        }}>
                    <CButton color="success" className="px-4" onClick={() => this.reloadData()}>Reload Data</CButton>
                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 
                    <CButton color="danger" className="px-4" onClick={() => { window.open('./#/price_tracker/expense/create', '_self'); }}> 🔗 Create a new expense</CButton>
                    </div>
                </h1>
                <div style={{
                        width:'70%',
                        borderStyle:"solid",
                        borderColor:"green",
                        padding: "10px 10px 10px 10px",
                        margin: "0px 0px 10px 0px"
                    }}>
                    <h3><u>Filters</u></h3>
                    <p>Filter applied ? : {this.state.filtersEngaged ? yesAndNoList[0].value : yesAndNoList[1].value } </p>
                    
                    <h4><CIcon size='lg' name="cilLocationPin" />&nbsp;&nbsp; temporal filter :</h4>
                    <CRow>
                        <CCol md="6">
                            <Select 
                                value={this.state.filterItems.temporalFilter}
                                onChange={(choice) => {
                                    const filterItems = this.state.filterItems;
                                    filterItems.temporalFilter = choice;
                                    this.setState({ filterItems });
                                }}
                                options={temporalFilterOptions}
                                isClearable={true}
                            />
                        </CCol>
                        <CCol md="6">
                            <CInput
                                placeholder="Date Of Purchase Filter" 
                                autoComplete="on"
                                type="date"
                                step="any"
                                id="dateOfPurchaseFilter"
                                value={this.state.filterItems.temporalValueFilter || ''}
                                onChange={(e) => {
                                    const filterItems = this.state.filterItems;
                                    filterItems.temporalValueFilter = e.target.value;
                                    this.setState({ filterItems });
                                }}
                                label="Date Of Purchase Filter"
                                required
                            />
                        </CCol>
                    </CRow>
                    <br />
                    
                    
                    <h4><CIcon size='lg' name="cilLocationPin" />&nbsp;&nbsp; category :</h4>
                    <Select 
                        value={this.state.filterItems.categoryFilter}
                        onChange={(choice) => {
                            const filterItems = this.state.filterItems;
                            filterItems.categoryFilter = choice;
                            this.setState({
                                filterItems
                            });
                        }}
                        options={this.state.categoryListData.map(cat => ({ value: cat.id, label: cat.name }))}
                        isClearable={true}
                    />
                    
                    
                    <h4><CIcon size='lg' name="cilLocationPin" />&nbsp;&nbsp; product :</h4>
                    <Select 
                        value={this.state.filterItems.productFilter}
                        onChange={(choice) => {
                            const filterItems = this.state.filterItems;
                            filterItems.productFilter = choice;
                            this.setState({
                                filterItems
                            });
                        }}
                        options={this.state.productListDataSelectTagSpecific}
                        isClearable={true}
                    />
                    <br />
                    <CButton color="warning" className="px-4" onClick={() => this.toggleFilter()}>Enable/apply/engage filters ?</CButton>
                    
                </div>
                <h3>table count : Σ {this.state.filteredExpensesListData.length}</h3>
                <br />
                <div style={{
                    maxHeight: '1000px',
                    overflow: 'auto'
                }}>
                <Table striped bordered hover color='success' style={{
                    textAlign:'left',
                    position: 'relative'
                }}>
                    <thead>
                        <tr style={{
                                position:'sticky',
                                background: 'white',
                                top: 0
                                }}>
                            <th>DB ID#</th>
                            <th>dateAndTimeOfPurchase</th>
                            <th>payment</th>
                            <th>items</th>
                            <th>mode</th>
                            <th>store</th>
                            <th>location</th>
                            <th>extraNotes</th>
                            <th>tags</th>
                        </tr>
                    </thead>
                    <tbody>
                        {
                            this.state.filteredExpensesListData.map(
                                entry => 
                                <tr key={"purchase_id_" + entry.expense.id}>
                                    <td>{entry.expense.id}</td>
                                    <td>{entry.expense.dateAndTimeOfPurchase}</td>

                                    <td>
                                        <tr>
                                            <th>totalAmount</th>
                                            <th>paymentInstrument</th>
                                            <th>bank</th>
                                        </tr>
                                        <tr>
                                            <td>₹{entry.payment.totalAmount}</td>
                                            <td>{entry.payment.paymentInstrument}</td>
                                            <td>{entry.payment.bank}</td>
                                        </tr>
                                    </td>

                                    <td>
                                        <tr>
                                            <th>#</th>
                                            <th>product name</th>
                                            <th>quantity</th>
                                            <th>amount</th>
                                        </tr>

                                        {
                                            entry.items.map(
                                                (itemDetail, count) => {
                                                    const product = itemDetail.product;
                                                    const category = itemDetail.category;
                                                    const unitLabel = category
                                                        ? (unitOfMeasurementsList.find(u => u.value === category.unitOfMeasurement) || {}).label || ''
                                                        : '';
                                                    return <tr key={"expense_item_id_" + itemDetail.item.id}>
                                                                <td>{count + 1}</td>
                                                                <td>{product ? product.name + ' (' + product.id + ')' : 'N/A'}</td>
                                                                <td>{itemDetail.item.quantity} {unitLabel}</td>
                                                                <td>₹ {itemDetail.item.amount}</td>
                                                            </tr>
                                            })
                                        }
                                    </td>

                                    <td>{entry.expense.mode}</td>
                                    <td>{this.printStoreData(entry)}</td>
                                    <td>{this.printLocationData(entry)}</td>
                                    <td>{entry.expense.extraNotes}</td>
                                    <td>{entry.expense.tags}</td>
                                </tr>
                            )
                        }
                    </tbody>
                </Table>
                </div>

                {/* //default */}
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
            : <Loading />
        );
    }
}

export default ExpensesView;
